import numpy as np

EPS = 1e-12

def safe_div(numerator, denominator):
    return numerator / (denominator + EPS)

def entropy(p, normalized=True):
    p = np.array(p, dtype=np.float32)
    if not normalized:
        p /= np.sum(p)
    ent = -1. * np.sum(p * np.log(p))
    return ent

from cocoa.model.manager import Manager as BaseManager

class Manager(BaseManager):
    def available_actions(self, state):
        actions = super(Manager, self).available_actions(state)
        masked_actions = []
        if state.curr_proposal is None:
            masked_actions.extend(['select', 'agree'])
        actions = [a for a in actions if not a in masked_actions]
        return actions

    def choose_action(self, state, context=None):
        action = super(Manager, self).choose_action(state, context)
        if action in ('select', 'agree') and not state.my_act in ('clarify', 'agree'):
            return 'clarify'
        if state.my_act == 'clarify':
            if state.partner_act in ('propose', 'insist'):
                if state.partner_proposal and state.partner_proposal != state.my_proposal:
                    return 'propose'
            if state.partner_act == 'disagree':
                return 'propose'
            return 'select'
        return action

from parser import LogicalForm as LF, Utterance

class DialogueState(object):
    def __init__(self, agent, kb):
        self.agent = agent
        self.partner = 1 - agent
        self.kb = kb
        self.time = 0
        init_utterance = Utterance(logical_form=LF('<start>'), template=['<start>'])
        self.utterance = [init_utterance, init_utterance]
        self.done = set()

    @property
    def my_act(self):
        return self.utterance[self.agent].lf.intent

    @property
    def partner_act(self):
        return self.utterance[self.partner].lf.intent

    @property
    def partner_utterance(self):
        return self.utterance[self.partner]

    @property
    def partner_template(self):
        try:
            return self.utterance[self.partner].template
        except:
            return None

    def update(self, agent, utterance):
        if not utterance:
            return
        self.time += 1
        self.utterance[agent] = utterance
        if agent == self.agent:
            self.done.add(utterance.lf.intent)

from cocoa.model.dialogue_state import DialogueState as State

class DialogueState(State):
    def __init__(self, agent, kb):
        super(DialogueState, self).__init__(agent, kb)
        self.entities = [[], []]
        self.exclude_entities = [[], []]
        self.mentioned_entities = set()
        self.recent_mentioned_entities = []
        self.matched_item = None
        self.selected_items = []

    @property
    def my_entities(self):
        return self.entities[self.agent]

    @my_entities.setter
    def my_entities(self, entities):
        self.entities[self.agent] = entities

    @property
    def partner_entities(self):
        return self.entities[self.partner]

    @property
    def partner_exclude_entities(self):
        return self.exclude_entities[self.partner]

    def update(self, agent, utterance):
        super(DialogueState, self).update(agent, utterance)
        lf = utterance.lf
        if lf.intent != 'select':
            if hasattr(lf, 'entities'):
                self.entities[agent] = lf.entities
                self.mentioned_entities.update(lf.entities)
                self.recent_mentioned_entities.extend(lf.entities)
                self.recent_mentioned_entities = self.recent_mentioned_entities[-10:]
            if hasattr(lf, 'exclude_entities'):
                self.exclude_entities[agent] = lf.exclude_entities
                self.mentioned_entities.update(lf.exclude_entities)
        else:
            self.selected_items.append(lf.item)
            if lf.matched:
                self.matched_item = lf.item

from cocoa.model.manager import Manager as BaseManager

class Manager(BaseManager):
    def available_actions(self, state):
        actions = super(Manager, self).available_actions(state)
        # These actions should be decided by the bot's strategy
        masked_actions = ['reject', 'accept', 'quit', 'agree']
        if state.num_inquiry > 1:
            masked_actions.append('inquiry')
            if state.curr_price is None:
                actions = ['init-price']
        if state.partner_price is None or state.curr_price is None:
            masked_actions.append('offer')
        actions = [a for a in actions if not a in masked_actions]
        return actions

    def choose_action(self, state, context=None):
        action = super(Manager, self).choose_action(state, context)
        if action == 'offer' and state.partner_act == 'unknown':
            return 'agree'
        return action
